import React, { useState } from 'react';
import { Layout, Typography, Space, Menu } from 'antd';
import {
  DashboardOutlined,
  AlertOutlined,
  WarningOutlined,
  FileTextOutlined,
  BarChartOutlined,
} from '@ant-design/icons';
import styled from 'styled-components';
import moment from 'moment';
import Overview from './pages/Overview';
import Accidents from './pages/Accidents';
import Violations from './pages/Violations';
import Reports from './pages/Reports';
import RiskWarning from './pages/RiskWarning';

const { Header, Content, Sider } = Layout;
const { Title } = Typography;

const StyledLayout = styled(Layout)`
  min-height: 100vh;
  background: #f0f2f5;
`;

const StyledHeader = styled(Header)`
  background: #1e3a8a;
  padding: 0 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: white;
`;

const StyledContent = styled(Content)`
  margin: 24px;
  overflow: auto;
`;

const StyledSider = styled(Sider)`
  background: #fff;
  box-shadow: 2px 0 8px rgba(0, 0, 0, 0.1);
`;

const StatusIndicator = styled.div<{ status: 'normal' | 'warning' | 'danger' }>`
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background-color: ${props => 
    props.status === 'normal' ? '#52c41a' : 
    props.status === 'warning' ? '#faad14' : '#f5222d'};
  margin-right: 8px;
`;

const App: React.FC = () => {
  const [selectedMenu, setSelectedMenu] = useState('overview');
  const trafficStatus = 'normal';

  const menuItems = [
    {
      key: 'overview',
      icon: <DashboardOutlined />,
      label: '交通态势总览',
    },
    {
      key: 'accidents',
      icon: <AlertOutlined />,
      label: '交通事故分析',
    },
    {
      key: 'violations',
      icon: <WarningOutlined />,
      label: '交通违法研判',
    },
    {
      key: 'risk-warning',
      icon: <AlertOutlined />,
      label: '交通风险预警',
    },
    {
      key: 'reports',
      icon: <BarChartOutlined />,
      label: '常用统计报表',
    },
  ];

  const handleMenuClick = (e: { key: string }) => {
    setSelectedMenu(e.key);
  };

  const renderContent = () => {
    switch (selectedMenu) {
      case 'overview':
        return <Overview />;
      case 'accidents':
        return <Accidents />;
      case 'violations':
        return <Violations />;
      case 'risk-warning':
        return <RiskWarning />;
      case 'reports':
        return <Reports />;
      default:
        return <Overview />;
    }
  };

  return (
    <StyledLayout>
      <StyledHeader>
        <Space>
          <Title level={3} style={{ color: 'white', margin: 0 }}>
            XX市公安交通管理分析平台
          </Title>
          <StatusIndicator status={trafficStatus} />
        </Space>
        <Space>
          <span>{moment().format('YYYY-MM-DD HH:mm:ss')}</span>
        </Space>
      </StyledHeader>
      
      <Layout>
        <StyledSider width={200}>
          <Menu
            mode="inline"
            selectedKeys={[selectedMenu]}
            style={{ height: '100%', borderRight: 0 }}
            items={menuItems}
            onClick={handleMenuClick}
          />
        </StyledSider>
        
        <StyledContent>
          {renderContent()}
        </StyledContent>
      </Layout>
    </StyledLayout>
  );
};

export default App;
